gab_(){return"\u0627\u0644\u0633\u0639\u0631 \u0627\u0644\u0623\u0639\u0644\u0649 \u0644\u0644\u0648\u062d\u062f\u0629"},
gaaZ(){return"\u0627\u062e\u062a\u064a\u0627\u0631\u064a. \u0627\u0644\u0648\u062d\u062f\u0627\u062a \u0627\u0644\u062a\u064a \u062a\u062a\u062c\u0627\u0648\u0632 \u0647\u0630\u0627 \u0627\u0644\u0639\u062f\u062f \u0641\u064a \u0627\u0644\u0634\u0647\u0631 (\u062d\u0633\u0628 \u062a\u0631\u062a\u064a\u0628 \u0625\u062f\u062e\u0627\u0644 \u0627\u0644\u062d\u0627\u0644\u0627\u062a) \u062a\u064f\u062d\u062a\u0633\u0628 \u0628\u0627\u0644\u0633\u0639\u0631 \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u0645\u062b\u0644\u0627\u064b \u0623\u0648\u0644 600 \u0648\u062d\u062f\u0629 \u0628\u0627\u0644\u0633\u0639\u0631 \u0627\u0644\u0639\u0627\u062f\u064a \u062b\u0645 1,500 \u0644\u0643\u0644 \u0648\u062d\u062f\u0629. \u0644\u0627 \u064a\u0624\u062b\u0631 \u0639\u0644\u0649 \u0623\u0633\u0639\u0627\u0631 \u0627\u0644\u0645\u0648\u0627\u062f \u0627\u0644\u062e\u0627\u0635\u0629. \u0627\u062a\u0631\u0643\u0647 \u0641\u0627\u0631\u063a\u0627\u064b \u0628\u062f\u0648\u0646."},
gaaq(){return"\u064a\u0648\u0645 \u0627\u0644\u0631\u0627\u062a\u0628 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a\u060c 1-28)"},
gaap(){return"\u062a\u064f\u062d\u062a\u0633\u0628 \u0627\u0644\u0639\u0645\u0648\u0644\u0629 \u0639\u0644\u0649 \u062d\u0627\u0644\u0627\u062a \u0647\u0630\u0627 \u0627\u0644\u0645\u0648\u0638\u0641 \u0645\u0646 \u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0630\u064a \u064a\u0644\u064a \u0647\u0630\u0627 \u0627\u0644\u064a\u0648\u0645 \u0625\u0644\u0649 \u0646\u0641\u0633 \u0627\u0644\u064a\u0648\u0645 \u0645\u0646 \u0627\u0644\u0634\u0647\u0631 \u0627\u0644\u062a\u0627\u0644\u064a (\u0645\u062b\u0644\u0627\u064b 4 = \u0645\u0646 5 \u0625\u0644\u0649 4). \u0627\u062a\u0631\u0643\u0647 \u0641\u0627\u0631\u063a\u0627\u064b \u0644\u0644\u0634\u0647\u0631 \u0627\u0644\u0645\u064a\u0644\u0627\u062f\u064a."},
