gEI(){return"\u0642\u0648\u0627\u0626\u0645 \u0627\u0644\u0637\u0644\u0628\u0627\u062a"},
gSy(){return"\u0644\u0627 \u062a\u0648\u062c\u062f \u0642\u0648\u0627\u0626\u0645 \u0637\u0644\u0628\u0627\u062a \u0628\u0639\u062f."},
gEG(){return"\u0642\u0627\u0626\u0645\u0629 \u062c\u062f\u064a\u062f\u0629"},
