SA(a){var s=""+a
return A.aH(a,s+" \u0623\u0635\u0646\u0627\u0641",this.a,s+" \u0635\u0646\u0641\u0627\u064b","\u0635\u0646\u0641 \u0648\u0627\u062d\u062f",s+" \u0635\u0646\u0641","\u0635\u0646\u0641\u0627\u0646",null)},
