ganf(){return"\u062a\u0639\u0630\u0651\u0631 \u0641\u062a\u062d \u0648\u0627\u062a\u0633\u0627\u0628 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632."},
a0Z(a,b,c,d){return"\u0645\u0631\u062d\u0628\u0627\u064b "+a+"\u060c\n\u062d\u0627\u0644\u062a\u0643 "+b+" \u0627\u0644\u0622\u0646 \u0641\u064a \u0645\u0631\u062d\u0644\u0629: "+c+".\n"+d},
galS(){return"\u0628\u0648\u062a \u062a\u064a\u0644\u064a\u062c\u0631\u0627\u0645"},
galL(){return"\u0628\u0648\u062a \u062a\u064a\u0644\u064a\u062c\u0631\u0627\u0645 \u062e\u0627\u0635 \u0628\u0645\u062e\u062a\u0628\u0631\u0643 \u0644\u0623\u0637\u0628\u0627\u0626\u0643: \u064a\u0631\u0633\u0644\u0648\u0646 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0645\u0639 \u0627\u0644\u0635\u0648\u0631 \u0648\u0645\u0644\u0641\u0627\u062a \u0627\u0644\u0645\u0633\u062d \u0645\u0646 \u062a\u064a\u0644\u064a\u062c\u0631\u0627\u0645\u060c \u0641\u062a\u0635\u0644 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0625\u0644\u0649 \u0637\u0644\u0628\u0627\u062a \u0627\u0644\u062d\u0627\u0644\u0627\u062a\u060c \u0648\u062a\u0635\u0644\u0647\u0645 \u0631\u0633\u0627\u0644\u0629 \u0639\u0646\u062f \u0643\u0644 \u0645\u0631\u062d\u0644\u0629. \u062a\u0634\u063a\u064a\u0644\u0647 \u0645\u062c\u0627\u0646\u064a."},
gLW(){return"\u0631\u0628\u0637 \u0628\u0648\u062a \u062a\u064a\u0644\u064a\u062c\u0631\u0627\u0645"},
galH(){return"\u0661. \u0641\u064a \u062a\u064a\u0644\u064a\u062c\u0631\u0627\u0645 \u0627\u0641\u062a\u062d @BotFather \u0648\u0623\u0631\u0633\u0644 \u200e/newbot.\n\u0662. \u0627\u062e\u062a\u0631 \u0627\u0633\u0645\u0627\u064b (\u0645\u062b\u0644\u0627\u064b \u0627\u0633\u0645 \u0645\u062e\u062a\u0628\u0631\u0643) \u0648\u0627\u0633\u0645 \u0645\u0633\u062a\u062e\u062f\u0645 \u064a\u0646\u062a\u0647\u064a \u0628\u0640 bot.\n\u0663. \u0633\u064a\u0631\u0633\u0644 \u0644\u0643 BotFather \u0631\u0645\u0632\u0627\u064b (token). \u0627\u0646\u0633\u062e\u0647 \u0643\u0627\u0645\u0644\u0627\u064b \u0648\u0627\u0644\u0635\u0642\u0647 \u0623\u062f\u0646\u0627\u0647."},
