galG(){return"\u0631\u0628\u0637"},
alR(a,b){return"\u0627\u0644\u0623\u0637\u0628\u0627\u0621 \u0627\u0644\u0645\u0631\u062a\u0628\u0637\u0648\u0646: "+a+" \xb7 \u0645\u062d\u0627\u062f\u062b\u0627\u062a \u0627\u0644\u0645\u062e\u062a\u0628\u0631 \u0627\u0644\u062a\u064a \u062a\u0635\u0644\u0647\u0627 \u0627\u0644\u062a\u0646\u0628\u064a\u0647\u0627\u062a: "+b},
