galM(){return"\u0644\u062a\u0635\u0644\u0643 \u0631\u0633\u0627\u0644\u0629 \u0639\u0646 \u0643\u0644 \u062d\u0627\u0644\u0629 \u064a\u0631\u0633\u0644\u0647\u0627 \u0627\u0644\u0623\u0637\u0628\u0627\u0621\u060c \u0627\u0641\u062a\u062d \u0627\u0644\u0628\u0648\u062a \u0648\u0623\u0631\u0633\u0644:"},
galN(){return"\u0631\u0645\u0632 \u062c\u062f\u064a\u062f"},
alF(a){return"\u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0648\u0627\u0631\u062f\u0629 \u0645\u0646 \u0627\u0644\u0628\u0648\u062a \u062a\u064f\u0633\u062c\u064e\u0651\u0644 \u0628\u0627\u0633\u0645 "+a+"."},
galI(){return"\u0641\u0635\u0644 \u0627\u0644\u0628\u0648\u062a"},
galK(){return"\u0641\u0635\u0644 \u0627\u0644\u0628\u0648\u062a\u061f"},
alJ(a){return"\u0633\u064a\u062a\u0648\u0642\u0641 "+a+" \u0639\u0646 \u0627\u0644\u0631\u062f \u0648\u0633\u064a\u064f\u062d\u0630\u0641 \u0627\u0631\u062a\u0628\u0627\u0637 \u0643\u0644 \u0637\u0628\u064a\u0628. \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0645\u0631\u0633\u0644\u0629 \u0633\u0627\u0628\u0642\u0627\u064b \u062a\u0628\u0642\u0649 \u0641\u064a IQ Labs."},
