ga0I(){return"\u0625\u0631\u0633\u0627\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649"},
ga0k(){return"\u0625\u0631\u0633\u0627\u0644 \u0625\u0644\u0649"},
a0N(a){return"\u0623\u064f\u0631\u0633\u0644\u062a \u0625\u0644\u0649 "+a},
a0K(a){return"\u062a\u0639\u0630\u0651\u0631 \u0627\u0644\u0625\u0631\u0633\u0627\u0644: "+a},
