galV(){return"\u0623\u0648\u060c \u0644\u062a\u0631\u0649 \u0643\u0644 \u0648\u0631\u0642\u0629 \u062a\u0631\u0633\u0644\u0647\u0627: \u0623\u0646\u0634\u0626 \u0645\u062c\u0645\u0648\u0639\u0629 \u062a\u064a\u0644\u064a\u062c\u0631\u0627\u0645 \u0645\u0639 \u062c\u0647\u0629 \u0627\u0644\u0627\u062a\u0635\u0627\u0644\u060c \u062b\u0645 \u0627\u0641\u062a\u062d \u0647\u0630\u0627 \u0627\u0644\u0631\u0627\u0628\u0637 \u0648\u0627\u062e\u062a\u0631 \u0627\u0644\u0645\u062c\u0645\u0648\u0639\u0629. \u0633\u062a\u0635\u0644 \u0627\u0644\u0623\u0648\u0631\u0627\u0642 \u0625\u0644\u0649 \u0627\u0644\u0645\u062c\u0645\u0648\u0639\u0629 \u0623\u0645\u0627\u0645\u0643\u0645\u0627 \u0645\u0639\u0627\u064b. \u0627\u0633\u062a\u062e\u062f\u0645 \u0631\u0627\u0628\u0637\u0627\u064b \u0648\u0627\u062d\u062f\u0627\u064b \u0641\u0642\u0637 \u0645\u0646 \u0627\u0644\u0627\u062b\u0646\u064a\u0646."},
alY(a,b){return a+" \xb7 \u0628\u0627\u0646\u062a\u0638\u0627\u0631 \xab\u0627\u0628\u062f\u0623\xbb (\u0627\u0644\u0631\u0627\u0628\u0637 \u0635\u0627\u0644\u062d \u062d\u062a\u0649 "+b+")"},
galZ(){return"\u0625\u0632\u0627\u0644\u0629"},
gam0(){return"\u0625\u0632\u0627\u0644\u0629 \u062c\u0647\u0629 \u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0647\u0630\u0647\u061f"},
