gaj4(){return"\u062f\u0627\u0634\u0628\u06c6\u0631\u062f"},
gair(){return"\u062f\u06cc\u0627\u0631\u06d5"},
gahV(){return"\u062a\u06d5\u0646\u0647\u0627 \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646\u06cc \u062e\u06c6\u06cc (\u062f\u06cc\u0632\u0627\u06cc\u0646\u06d5\u0631 \u06cc\u0627\u0646 \u0633\u06cc\u0631\u0627\u0645\u06cc\u0633\u062a \u0626\u06d5\u0648 \u06a9\u06d5\u06cc\u0633\u0627\u0646\u06d5 \u062f\u06d5\u0628\u06cc\u0646\u06ce\u062a \u06a9\u06d5 \u062e\u06c6\u06cc \u0648\u06d5\u0631\u06cc\u06af\u0631\u062a\u0648\u0648\u0646\u060c \u0648 \u0647\u06d5\u0631 \u062a\u06d5\u06a9\u0646\u06cc\u0633\u06cc\u0627\u0646\u06ce\u06a9 \u0626\u06d5\u0648 \u06a9\u06d5\u06cc\u0633\u0627\u0646\u06d5\u06cc \u0628\u06c6\u06cc \u062f\u06cc\u0627\u0631\u06cc\u06a9\u0631\u0627\u0648\u0646\u061b \u0644\u06d5\u06af\u06d5\u06b5 \u0626\u06d5\u0648 \u06a9\u06d5\u06cc\u0633\u0627\u0646\u06d5\u06cc \u0647\u06ce\u0634\u062a\u0627 \u06a9\u06d5\u0633 \u0648\u06d5\u0631\u06cc\u0646\u06d5\u06af\u0631\u062a\u0648\u0648\u06d5 \u0648 \u0628\u06c6 \u06a9\u06d5\u0633 \u062f\u06cc\u0627\u0631\u06cc\u0646\u06d5\u06a9\u0631\u0627\u0648\u06d5)"},
gahT(){return"\u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u0642\u06c6\u0646\u0627\u063a\u06cc \u06a9\u06d5\u06cc\u0633 \u0628\u06d5\u0631\u06d5\u0648\u067e\u06ce\u0634 \u0628\u0628\u0627\u062a"},
gahS(){return"\u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u0628\u06d5 \u062f\u0648\u06af\u0645\u06d5 \u0642\u06c6\u0646\u0627\u063a \u0628\u06d5\u0631\u06d5\u0648\u067e\u06ce\u0634 \u0628\u0628\u0627\u062a (\u06a9\u0648\u0698\u0627\u0646\u062f\u0646\u06d5\u0648\u06d5 = \u062a\u06d5\u0646\u0647\u0627 \u0628\u06d5 \u0633\u06a9\u0627\u0646\u06cc \u0628\u0627\u0631\u06a9\u06c6\u062f)"},
gahU(){return"\u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u067e\u0633\u0648\u0648\u0644\u06d5\u06cc \u067e\u0632\u06cc\u0634\u06a9 \u0686\u0627\u067e \u0628\u06a9\u0627\u062a"},
gahY(){return"\u0633\u062a\u0648\u0648\u0646\u06d5 \u0642\u06c6\u0646\u0627\u063a\u06d5 \u062f\u06cc\u0627\u0631\u06d5\u06a9\u0627\u0646"},
gahX(){return"\u0647\u06d5\u0645\u0648\u0648 \u0642\u06c6\u0646\u0627\u063a\u06d5\u06a9\u0627\u0646 \u0628\u06ce \u0647\u06d5\u06b5\u0628\u0698\u0627\u0631\u062f\u0646 \u0628\u0647\u06ce\u06b5\u06d5\u0631\u06d5\u0648\u06d5 \u0628\u06c6 \u0626\u06d5\u0648\u06d5\u06cc \u0626\u06d5\u0645 \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u06d5 \u0647\u06d5\u0645\u0648\u0648 \u0628\u06c6\u0631\u062f\u06d5\u06a9\u06d5 \u0628\u0628\u06cc\u0646\u06ce\u062a. \u0647\u06d5\u06b5\u0628\u0698\u0627\u0631\u062f\u0646\u06cc \u06cc\u06d5\u06a9 \u06cc\u0627\u0646 \u0686\u06d5\u0646\u062f \u0642\u06c6\u0646\u0627\u063a \u0647\u06d5\u0645\u0648\u0648 \u0633\u062a\u0648\u0648\u0646\u06d5\u06a9\u0627\u0646\u06cc \u062a\u0631 \u0644\u06ce\u06cc \u062f\u06d5\u0634\u0627\u0631\u06ce\u062a\u06d5\u0648\u06d5."},
gahW(){return"\u0647\u06ce\u0634\u062a\u0627 \u0647\u06cc\u0686 \u0642\u06c6\u0646\u0627\u063a\u06cc \u0628\u06d5\u0631\u0647\u06d5\u0645\u0647\u06ce\u0646\u0627\u0646 \u0646\u06cc\u06cc\u06d5 \u0628\u06c6 \u0695\u06ce\u06a9\u062e\u0633\u062a\u0646."},
gahR(){return"\u0626\u06d5\u0648 \u0642\u06c6\u0646\u0627\u063a\u0627\u0646\u06d5\u06cc \u0626\u06d5\u0645 \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u06d5 \u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u06a9\u06d5\u06cc\u0633\u06cc\u0627\u0646 \u0644\u06ce \u0628\u06d5\u0631\u06d5\u0648\u067e\u06ce\u0634 \u0628\u0628\u0627\u062a"},
gahQ(){return"\u0626\u06d5\u0648 \u0642\u06c6\u0646\u0627\u063a\u0627\u0646\u06d5\u06cc \u0626\u06d5\u0645 \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u06d5 \u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u06a9\u06d5\u06cc\u0633\u06cc\u0627\u0646 \u0644\u06ce \u0628\u06af\u0648\u0627\u0632\u06ce\u062a\u06d5\u0648\u06d5: \u0628\u06d5 \u062f\u0648\u06af\u0645\u06d5\u06a9\u0627\u0646\u06cc \u0628\u06c6\u0631\u062f \u0648 \u0644\u06d5 \u0648\u0631\u062f\u06d5\u06a9\u0627\u0631\u06cc \u06a9\u06d5\u06cc\u0633 \u0648 \u0628\u06d5 \u0633\u06a9\u0627\u0646. \u0644\u06d5 \u062f\u0627\u062a\u0627\u0628\u06d5\u06cc\u0633\u06d5\u0648\u06d5 \u062c\u06ce\u0628\u06d5\u062c\u06ce \u062f\u06d5\u06a9\u0631\u06ce\u062a. \u0647\u06d5\u0645\u0648\u0648 \u0642\u06c6\u0646\u0627\u063a\u06d5\u06a9\u0627\u0646 \u0628\u06d5\u0628\u06ce \u0647\u06d5\u06b5\u0628\u0698\u0627\u0631\u062f\u0646 \u0628\u0647\u06ce\u06b5\u06d5\u0631\u06d5\u0648\u06d5 \u0628\u06c6 \u0695\u06ce\u06af\u06d5\u062f\u0627\u0646 \u0628\u06d5 \u0647\u06d5\u0645\u0648\u0648\u06cc\u0627\u0646. \u0628\u06d5\u0695\u06ce\u0648\u06d5\u0628\u06d5\u0631\u0627\u0646 \u0647\u06d5\u0631\u06af\u06cc\u0632 \u0633\u0646\u0648\u0648\u0631\u062f\u0627\u0631 \u0646\u0627\u06a9\u0631\u06ce\u0646. \u0628\u06c6 \u0626\u06d5\u0648\u06d5\u06cc \u0647\u06d5\u0631\u06af\u06cc\u0632 \u0646\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u06a9\u06d5\u06cc\u0633 \u0628\u06d5\u0631\u06d5\u0648\u067e\u06ce\u0634 \u0628\u0628\u0627\u062a\u060c \xab\u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u0642\u06c6\u0646\u0627\u063a\u06cc \u06a9\u06d5\u06cc\u0633 \u0628\u06d5\u0631\u06d5\u0648\u067e\u06ce\u0634 \u0628\u0628\u0627\u062a\xbb \u0644\u06d5 \u0633\u06d5\u0631\u06d5\u0648\u06d5 \u0628\u06a9\u0648\u0698\u06ce\u0646\u06d5\u0631\u06d5\u0648\u06d5."},
gLd(){return"\u06a9\u06c6\u067e\u06cc \u0644\u06d5\u2026"},
gaj0(){return"\u0647\u06d5\u0645\u0648\u0648 \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646"},
gaif(){return"\u062f\u06cc\u0627\u0631\u06d5"},
gaiZ(){return"\u062f\u0631\u0648\u0633\u062a\u06a9\u0631\u062f\u0646 \u0648 \u062f\u06d5\u0633\u062a\u06a9\u0627\u0631\u06cc\u06a9\u0631\u062f\u0646\u06cc \u06a9\u06d5\u06cc\u0633"},
gai4(){return"\u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u06a9\u06d5\u06cc\u0633\u06ce\u06a9\u06cc \u0646\u0648\u06ce \u062f\u0631\u0648\u0633\u062a \u0628\u06a9\u0627\u062a (\u06cc\u0627\u0646 \u062f\u0648\u0648\u0628\u0627\u0631\u06d5\u06cc \u0628\u06a9\u0627\u062a\u06d5\u0648\u06d5)"},
gaic(){return"\u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u0646\u0631\u062e \u0648 \u062a\u06ce\u0686\u0648\u0648 \u062f\u06cc\u0627\u0631\u06cc \u0628\u06a9\u0627\u062a/\u0628\u06cc\u06af\u06c6\u0695\u06ce\u062a"},
gaie(){return"\u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u0646\u0631\u062e \u0648 \u062a\u06ce\u0686\u0648\u0648 \u0648 \u0642\u0627\u0632\u0627\u0646\u062c \u0628\u0628\u06cc\u0646\u06ce\u062a \u0644\u06d5 \u06a9\u06d5\u06cc\u0633\u062f\u0627"},
