gaia(){return"\u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u0644\u06d5\u06cc\u0628\u06b5 / \u067e\u0633\u0648\u0648\u0644\u06d5\u06cc \u0686\u0627\u0648\u062f\u06ce\u0631\u06cc \u0686\u0627\u067e \u0628\u06a9\u0627\u062a"},
gai9(){return"\u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u0646\u0627\u0645\u06d5 \u0628\u06c6 \u06a9\u0644\u06cc\u0646\u06cc\u06a9 \u0628\u0646\u06ce\u0631\u06ce\u062a"},
gaj2(){return"\u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06d5\u06a9\u0627\u0646"},
gail(){return"\u062f\u06cc\u0627\u0631\u06d5"},
gaik(){return"\u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u06a9\u0644\u06cc\u0646\u06cc\u06a9 \u0648 \u067e\u0632\u06cc\u0634\u06a9 \u0632\u06cc\u0627\u062f/\u062f\u06d5\u0633\u062a\u06a9\u0627\u0631\u06cc \u0628\u06a9\u0627\u062a\u060c \u0646\u0631\u062e\u06cc \u067e\u0632\u06cc\u0634\u06a9 \u062f\u06cc\u0627\u0631\u06cc \u0628\u06a9\u0627\u062a\u060c \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u062f\u0646 \u067e\u06d5\u0633\u06d5\u0646\u062f \u0628\u06a9\u0627\u062a"},
gaij(){return"\u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u06a9\u0644\u06cc\u0646\u06cc\u06a9 \u06cc\u0627\u0646 \u067e\u0632\u06cc\u0634\u06a9\u06ce\u06a9 \u0628\u0633\u0695\u06ce\u062a\u06d5\u0648\u06d5 \u06a9\u06d5 \u0647\u06cc\u0686 \u06a9\u06d5\u06cc\u0633 \u0648 \u067e\u0627\u0631\u06d5\u062f\u0627\u0646 \u0648 \u0633\u06d5\u0631\u062f\u0627\u0646 \u0648 \u0642\u06d5\u0631\u0632\u06cc \u0646\u06cc\u06cc\u06d5 (\u0628\u06d5\u0695\u06ce\u0648\u06d5\u0628\u06d5\u0631\u0627\u0646 \u0632\u06cc\u0627\u062a\u0631 \u062f\u06d5\u0633\u0695\u0646\u06d5\u0648\u06d5)"},
