gaiv(){return"\u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u067e\u0632\u06cc\u0634\u06a9\u06ce\u06a9\u06cc \u062a\u06d5\u0646\u0647\u0627-\u0628\u06c6-\u0633\u06d5\u0631\u062f\u0627\u0646 \u062f\u06d5\u0633\u062a\u06a9\u0627\u0631\u06cc \u06cc\u0627\u0646 \u0646\u0627\u0686\u0627\u0644\u0627\u06a9 \u0628\u06a9\u0627\u062a"},
gait(){return"\u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u067e\u0632\u06cc\u0634\u06a9\u06ce\u06a9\u06cc \u062a\u06d5\u0646\u0647\u0627-\u0628\u06c6-\u0633\u06d5\u0631\u062f\u0627\u0646 \u0628\u06d5 \u062a\u06d5\u0648\u0627\u0648\u06cc \u0628\u0633\u0695\u06ce\u062a\u06d5\u0648\u06d5"},
gaiw(){return"\u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u0633\u06d5\u0631\u062f\u0627\u0646\u06ce\u06a9 \u062a\u06c6\u0645\u0627\u0631 \u0628\u06a9\u0627\u062a"},
