ga29(){return"\u06a9\u06c6\u0645\u0628\u06c6\u06a9\u0627\u0646"},
ga28(){return"\u067e\u06ce\u0634\u06d5\u06a9\u06cc\u06cc \u0626\u0627\u0645\u0627\u062f\u06d5\u06a9\u0631\u0627\u0648 \u0628\u06c6 \u062c\u06c6\u0631\u06d5 \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646\u06cc \u0647\u06d5\u0645\u06cc\u0634\u06d5 \u067e\u06ce\u06a9\u06d5\u0648\u06d5 \u062f\u0631\u0648\u0633\u062a\u06a9\u0631\u0627\u0648 (\u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5 \u0626\u06cc\u0645\u067e\u0644\u0627\u0646\u062a + \u062a\u0627\u062c) \u2014 \u06cc\u06d5\u06a9\u06ce\u06a9\u06cc\u0627\u0646 \u0647\u06d5\u06b5\u0628\u0698\u06ce\u0631\u06d5 \u0644\u06d5 \u06a9\u06d5\u06cc\u0633\u06cc \u0646\u0648\u06ce \u0628\u06c6 \u0626\u06d5\u0648\u06d5\u06cc \u0647\u06d5\u0645\u0648\u0648 \u062c\u06c6\u0631\u06d5\u06a9\u0627\u0646 \u06cc\u06d5\u06a9\u062c\u0627\u0631 \u062f\u0631\u0648\u0633\u062a \u0628\u06a9\u0631\u06ce\u0646."},
