ga6M(){return"\u06af\u06d5\u0695\u0627\u0646\u2026"},
a6O(a,b){return"\u0646\u06cc\u0634\u0627\u0646\u062f\u0627\u0646\u0627 "+a+" \u0698 "+b},
ga6N(){return"\u067e\u062a\u0631 \u0646\u06cc\u0634\u0627\u0646 \u0628\u062f\u06d5"},
ga6K(){return"\u0686 \u062a\u0634\u062a \u0644 \u06a4\u06ce\u0631\u06ce \u0646\u06cc\u0646\u0646."},
ga6n(){return"\u06a9\u06d5\u06cc\u0633"},
